import re, io
pats = {
 "① float(/注解": re.compile(r"float\(|:\s*float"),
 "② /100 真除法": re.compile(r"(^|[^/])/\s*100([^0-9]|$)"),
}
files = ["ok.py","bad.py"]
for name, rx in pats.items():
    print(f"--- {name} ---")
    for f in files:
        hits=[]
        for i,line in enumerate(io.open(f,encoding="ascii"),1):
            if rx.search(line): hits.append(f"{f}:{i}:{line.rstrip()}")
        print(f"{f}: hits={len(hits)}  exit_code={'0' if hits else '1'}")
        for h in hits: print("   ",h)
